const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lake Langano geometry (rough polygon based on visual inspection)
  const langano = ee.Geometry.Polygon(
    [[[38.749, 7.640],
      [38.749, 7.371],
      [38.903, 7.371],
      [38.903, 7.640]]]);

  // Lake Abijata geometry (rough polygon based on visual inspection)
  const abijata = ee.Geometry.Polygon(
    [[[38.608, 7.766],
      [38.608, 7.561],
      [38.743, 7.561],
      [38.743, 7.766]]]);

  const date = ee.Date('2022-03-29');
  const dateRange = date.advance(-5, 'day').getRange(10, 'day'); // +/- 5 days

  // Cloud masking function for Sentinel-2 SR
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
  }

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateRange)
    .filterBounds(langano.union(abijata)) // Filter by both lakes combined
    .map(maskS2clouds)
    .select(['B4']); // Select Red band for 'brownness' assessment

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No Sentinel-2 images found for the specified date range and location.");
    console.log("C1");
    return;
  }

  // Get the closest image to the target date
  const targetDateMillis = date.millis();
  const closestImage = collection.map(function(image) {
    return image.set('date_delta', ee.Number(image.date().millis()).subtract(targetDateMillis).abs());
  }).sort('date_delta').first();

  if (closestImage === null) {
      console.log("No valid images found after filtering and sorting.");
      console.log("C1");
      return;
  }

  const imageDate = await ee.Date(closestImage.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  console.log(`Analyzing image from: ${imageDate}`);

  // Calculate MNDWI to create a water mask
  function addMNDWI(image) {
    // Green (B3), SWIR1 (B11)
    return image.addBands(image.normalizedDifference(['B3', 'B11']).rename('MNDWI'));
  }
  const processedImage = addMNDWI(closestImage.unmask(0)); // Unmask to calculate MNDWI everywhere first
  const waterMask = processedImage.select('MNDWI').gt(0.1); // Simple threshold for water

  // Apply water mask to the original image for relevant pixels
  const maskedImage = closestImage.updateMask(waterMask);

  // 3. Processing & Calculation for Lake Langano
  const langanoCount = await maskedImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: langano,
    scale: 30, // Sentinel-2 resolution
    maxPixels: 1e9,
    tileScale: 16
  }).get('B4').getInfo();

  if (langanoCount === 0 || langanoCount === null) {
    console.log("No valid water pixels found for Lake Langano after masking.");
    console.log("C2");
    return;
  }

  const langanoRedMean = await maskedImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: langano,
    scale: 30,
    maxPixels: 1e9,
    tileScale: 16
  }).get('B4').getInfo();

  // 4. Processing & Calculation for Lake Abijata
  const abijataCount = await maskedImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: abijata,
    scale: 30,
    maxPixels: 1e9,
    tileScale: 16
  }).get('B4').getInfo();

  if (abijataCount === 0 || abijataCount === null) {
    console.log("No valid water pixels found for Lake Abijata after masking.");
    console.log("C2");
    return;
  }

  const abijataRedMean = await maskedImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: abijata,
    scale: 30,
    maxPixels: 1e9,
    tileScale: 16
  }).get('B4').getInfo();

  // 5. Validation & Final Answer
  if (langanoRedMean === null || abijataRedMean === null ||
      typeof langanoRedMean === 'undefined' || typeof abijataRedMean === 'undefined') {
    console.log("Calculation resulted in None/NaN for mean Red reflectance.");
    console.log("C3");
    return;
  }

  console.log(`Lake Langano (Red Mean): ${langanoRedMean.toFixed(4)} (Pixels: ${langanoCount})`);
  console.log(`Lake Abijata (Red Mean): ${abijataRedMean.toFixed(4)} (Pixels: ${abijataCount})`);

  // Higher Red reflectance implies more "brownness"
  if (langanoRedMean > abijataRedMean) {
    console.log("A"); // Yes, Lake Langano is more brown
  } else {
    console.log("B"); // No, Lake Langano is not more brown
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
